protection_check.command:
node - <<'NODE'
const fs=require('fs'),crypto=require('crypto');const sha=b=>crypto.createHash('sha256').update(b).digest('hex');const desc=p=>{const b=fs.readFileSync(p);return {path:p,bytes:b.length,sha256:sha(b)}};const lock=JSON.parse(fs.readFileSync('BATCH_ROUND10_STAGE4_5_ROUND4_INPUT_LOCK.json'));const mismatches=[];for(const x of lock.protected_files){try{const d=desc(x.path);if(d.bytes!==x.bytes||d.sha256!==x.sha256)mismatches.push({expected:x,actual:d});}catch(e){mismatches.push({path:x.path,error:String(e)});}}
function walk(p){let o=[];for(const e of fs.readdirSync(p,{withFileTypes:true})){const q=p+'/'+e.name;if(e.isSymbolicLink())o.push({path:q,kind:'symlink'});else if(e.isDirectory())o.push(...walk(q));else o.push(desc(q));}return o.sort((a,b)=>a.path.localeCompare(b.path));}
const trees=lock.protected_science_trees.map(x=>{const files=walk(x.path);const exp=[...x.files].sort((a,b)=>a.path.localeCompare(b.path));return {path:x.path,file_count:files.length,unchanged:JSON.stringify(files)===JSON.stringify(exp),files};});const outputs=[];for(const p of lock.papers){for(const e of fs.readdirSync('papers/'+p.paper_slug+'/notes',{withFileTypes:true})){if(e.isFile()&&e.name.startsWith('stage4_5_round4_'))outputs.push(desc('papers/'+p.paper_slug+'/notes/'+e.name));}}for(const e of fs.readdirSync('.',{withFileTypes:true})){if(e.isFile()&&e.name.startsWith('BATCH_ROUND10_STAGE4_5_ROUND4_'))outputs.push(desc(e.name));}
const p='papers/31-level11-conjugacy-owner-ledger/notes/';const x=JSON.parse(fs.readFileSync(p+'stage4_5_round4_web_crossref.json'));const rows=x.output.trim().split('\n').map(JSON.parse);const retry=JSON.parse(JSON.parse(fs.readFileSync(p+'stage4_5_round4_web_s16_retry.json')).output);console.log(JSON.stringify({observed_at_utc:new Date().toISOString(),input_lock:desc('BATCH_ROUND10_STAGE4_5_ROUND4_INPUT_LOCK.json'),authorization:desc(lock.authorization.path),protected_files_checked:lock.protected_files.length,protected_mismatches:mismatches,science_trees:trees,new_audit_file_inventory:outputs.sort((a,b)=>a.path.localeCompare(b.path)),incident_evidence:[desc(p+'stage4_5_round4_web_crossref.json'),desc(p+'stage4_5_round4_web_s16_retry.json')],request_summary:{initial_request_count:rows.length,initial_status_counts:rows.reduce((a,r)=>(a[r.status]=(a[r.status]||0)+1,a),{}),first_confirmed_time:rows.map(r=>r.checked_at).filter(Boolean).sort()[0],last_confirmed_time:rows.map(r=>r.checked_at).filter(Boolean).sort().at(-1),retry:{url:retry.url,status:retry.status,retrieved_at:retry.retrieved_at},total_request_count:rows.length+1,urls:rows.map(r=>r.url)}}));
NODE
